7\u0435\u0433\u043e.\n- \u0417\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0435\u0439 \u043d\u0435\u0442, \u043a\u0430\u043a \u0438 \u043e\u0436\u0438\u0434\u0430\u043b\u043e\u0441\u044c: `python3` = 3.14.4; `import torch`, `import torchopt`, `import torchviz`, `import graphviz` \u2014 \u0432\u0441\u0435 ModuleNotFoundError. `dot` (graphviz CLI) \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d. \u041e\u0444\u0444\u043b\u0430\u0439\u043d-\u043a\u043e\u043b\u0451\u0441 \u0438 pip-\u043a\u044d\u0448\u0430 \u043d\u0435\u0442; \u0441\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430, \u0442\u0430\u043a \u0447\u0442\u043e \u0441\u043a\u043b\u043e\u043d\u0438\u0440\u043e\u0432\u0430\u0442\u044c/\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u0441\u0435\u0439\u0447\u0430\u0441 \u043d\u0435\u043b\u044c\u0437\u044f. git 2.53.0 \u0444\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u043e \u0435\u0441\u0442\u044c.\n- \u0421\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u0435: \u043d\u0438 \u043e\u0434\u0438\u043d API-\u0434\u0435\u0442\u0430\u043b\u044c\u043d\u044b\u0439 \u0442\u0435\u0437\u0438\u0441 \u043d\u0438\u0436\u0435 \u043d\u0435 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u0441\u0435\u0439\u0447\u0430\u0441 \u0432\u0435\u0440\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d \u043f\u043e \u0438\u0441\u0445\u043e\u0434\u043d\u0438\u043a\u0430\u043c \u2014 \u0432\u0441\u0451, \u0447\u0442\u043e \u043a\u0430\u0441\u0430\u0435\u0442\u0441\u044f \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u044b\u0445 \u043c\u043e\u0434\u0443\u043b\u0435\u0439/\u0441\u0438\u0433\u043d\u0430\u0442\u0443\u0440, \u043f\u043e\u043c\u0435\u0447\u0435\u043d\u043e \u043a\u0430\u043a [ASSUMPTION-PRIOR] (\u043c\u043e\u0438 \u043f\u0440\u0435\u0434\u044b\u0434\u0443\u0449\u0438\u0435 \u0437\u043d\u0430\u043d\u0438\u044f \u043e \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u0445 API, \u043f\u043e\u0434\u043b\u0435\u0436\u0430\u0449\u0438\u0435 \u0441\u0432\u0435\u0440\u043a\u0435 \u043f\u0440\u0438 \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u0438\u0438 \u0440\u0435\u043f\u043e).\n\n\u0422\u043e\u0447\u043a\u0438, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u044f \u0431\u0443\u0434\u0443 \u0441\u043c\u043e\u0442\u0440\u0435\u0442\u044c \u043a\u0430\u043a \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0444\u0430\u043a\u0442\u043e\u0432, \u043a\u043e\u0433\u0434\u0430 \u0440\u0435\u043f\u043e \u043f\u043e\u044f\u0432\u044f\u0442\u0441\u044f:\n- TorchOpt: `torchopt/__init__.py` (\u044d\u043a\u0441\u043f\u043e\u0440\u0442\u044b `adam`, `chain`, `compose`, `update`/`init` \u0444\u0443\u043d\u043a\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0433\u043e API); `torchopt/transform_mapping/classic.py` (\u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f adam-\u043f\u0440\u0435\u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u043d\u0438\u044f); `torchopt/functools/chain.py` (\u0446\u0435\u043f\u043e\u0447\u043a\u0430 \u0442\u0440\u0430\u043d\u0441\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u0439); `torchopt/optimizer/adam.py` (\u043a\u043b\u0430\u0441\u0441 Adam \u0441\u043e stateful `step_`); \u043f\u043e\u0438\u0441\u043a \u0432\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0439 `fused` / `torch.compile` / `torch.jit` \u0434\u043b\u044f \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f, \u0447\u0442\u043e \u0438\u043c\u0435\u043d\u043d\u043e \u0437\u043d\u0430\u0447\u0438\u0442 \u00abfusing\u00bb \u0432 TorchOpt [ASSUMPTION-PRIOR: fused \u2014 \u044d\u0442\u043e \u043a\u043e\u043c\u043f\u0438\u043b\u044f\u0446\u0438\u044f \u0448\u0430\u0433\u0430 \u0447\u0435\u0440\u0435\u0437 torch.compile, \u0430 \u043d\u0435 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 CUDA-\u043a\u0435\u0440\u043d\u0435\u043b]; `examples/` \u0438 `tests/test_optimizers*`; \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430\u0446\u0438\u044f \u2014 \u043f\u0440\u0438\u043f\u043e\u043c\u0438\u043d\u0430\u044e \u0442\u0443\u0442\u043e\u0440\u0438\u0430\u043b TorchOpt, \u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u044e\u0449\u0438\u0439 \u0433\u0440\u0430\u0444\u044b \u0447\u0435\u0440\u0435\u0437 torchviz [ASSUMPTION-PRIOR \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c; \u0435\u0441\u043b\u0438 \u0435\u0441\u0442\u044c, \u044d\u0442\u043e \u043f\u0440\u044f\u043c\u043e\u0439 \u044f\u043a\u043e\u0440\u044c \u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u043e\u0432\u043a\u0438 \u0432\u043e\u043f\u0440\u043e\u0441\u0430].\n- TorchViz: `torchviz/__init__.py` \u2014 `make_dot` / `make_dot_from_trace`, \u043a\u0430\u043a \u0441\u0442\u0440\u043e\u0438\u0442\u0441\u044f Digraph \u0438\u0437 `grad_fn` (`next_functions`, \u043b\u0438\u0441\u0442\u044c\u044f `AccumulateGrad`/\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b), \u043e\u043f\u0446\u0438\u044f `params`; `tests/` \u0438 \u043f\u0440\u0438\u043c\u0435\u0440\u044b \u0440\u0435\u043d\u0434\u0435\u0440\u0438\u043d\u0433\u0430.\n\n## 2) \u041f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u0435\u043c\u044b\u0439 \u043f\u043e\u0434\u0445\u043e\u0434 \u043a \u0434\u0438\u0437\u0430\u0439\u043d\u0443 (\u0431\u0435\u0437 \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f)\n\n**\u0413\u043b\u0430\u0432\u043d\u044b\u0439 \u043c\u0435\u0442\u043e\u0434\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043a\u0430\u0440\u043a\u0430\u0441 (\u0447\u0442\u043e\u0431\u044b \u043d\u0435 \u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0442\u044c \u043d\u0435\u0441\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u043c\u043e\u0435).** TorchOpt \u2014 \u0431\u0438\u0431\u043b\u0438\u043e\u0442\u0435\u043a\u0430 \u0442\u0440\u0430\u043d\u0441\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u0439 \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0442\u043e\u0440\u0430, TorchViz \u2014 \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442 \u0432\u0438\u0437\u0443\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438; \u044d\u0442\u043e \u043d\u0435 \u0434\u0432\u0430 \u043a\u043e\u043d\u043a\u0443\u0440\u0438\u0440\u0443\u044e\u0449\u0438\u0445 \u0440\u0435\u043d\u0434\u0435\u0440\u0435\u0440\u0430 \u0433\u0440\u0430\u0444\u043e\u0432. \u041a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u0430\u044f \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0432\u043e\u043f\u0440\u043e\u0441\u0430: \u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u044e\u0442\u0441\u044f **\u0433\u0440\u0430\u0444\u044b \u043e\u0434\u043d\u043e\u0433\u043e \u0438 \u0442\u043e\u0433\u043e \u0436\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u0441\u043e\u0431\u044b\u0442\u0438\u044f**, \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u043d\u044b\u0435 \u043f\u0440\u0438 \u0440\u0430\u0437\u043d\u044b\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445 \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u0438\u044f, \u0438 **\u0438\u0437\u0432\u043b\u0435\u0447\u0451\u043d\u043d\u044b\u0435 \u043e\u0434\u043d\u0438\u043c \u0438 \u0442\u0435\u043c \u0436\u0435 \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442\u043e\u043c**. TorchViz \u0432\u0445\u043e\u0434\u0438\u0442 \u0432 \u0434\u0438\u0437\u0430\u0439\u043d \u0434\u0432\u0430\u0436\u0434\u044b: (\u0430) \u043a\u0430\u043a \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u00aboutput from TorchViz\u00bb \u2014 \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0439 baseline-\u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442, \u0443\u043f\u043e\u043c\u044f\u043d\u0443\u0442\u044b\u0439 \u0432 \u0432\u043e\u043f\u0440\u043e\u0441\u0435; (\u0431) \u043a\u0430\u043a \u043e\u0431\u0449\u0438\u0439 \u044d\u043a\u0441\u0442\u0440\u0430\u043a\u0442\u043e\u0440 \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u0439, \u0433\u0434\u0435 \u044d\u0442\u043e \u0442\u0435\u0445\u043d\u0438\u0447\u0435\u0441\u043a\u0438 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e.\n\n(a) **\u0415\u0434\u0438\u043d\u0438\u0446\u0430 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f (apples-to-apples).** \u041e\u0434\u0438\u043d Adam-\u0448\u0430\u0433 (forward + backward + optimizer.step) \u043d\u0430 \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u043e\u0439 \u043c\u0430\u043b\u043e\u0439 \u043c\u043e\u0434\u0435\u043b\u0438 (MLP 2\u20133 \u0441\u043b\u043e\u044f, \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0440\u0430\u0437\u043c\u0435\u0440\u044b, float32, CPU, seed), \u043e\u0434\u0438\u043d \u0438 \u0442\u043e\u0442 \u0436\u0435 \u0432\u0445\u043e\u0434\u043d\u043e\u0439 \u0442\u0435\u043d\u0437\u043e\u0440. \u0412\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0439 \u0431\u043b\u043e\u043a \u2014 100 \u0448\u0430\u0433\u043e\u0432 \u043f\u043e\u0441\u043b\u0435 \u043f\u0440\u043e\u0433\u0440\u0435\u0432\u0430 (\u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u0435 Adam momentum/variance \u043d\u0435\u043f\u0443\u0441\u0442\u043e\u0435 \u2014 \u0438\u043d\u0430\u0447\u0435 \u0448\u0430\u0433 \u043d\u0435\u0440\u0430\u0432\u043d\u043e\u0446\u0435\u043d\u0435\u043d). \u0423\u0441\u043b\u043e\u0432\u0438\u044f (3 \u0440\u0443\u043a\u0438):\n  1. **A \u2014 \u043d\u0430\u0442\u0438\u0432\u043d\u044b\u0439 `torch.optim.Adam.step()`**, \u0433\u0440\u0430\u0444 \u0447\u0435\u0440\u0435\u0437 `torchviz.make_dot(loss)`;\n  2. **B \u2014 TorchOpt Adam (stateful `step_` \u0438 \u0444\u0443\u043d\u043a\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0439 `init/update` \u043a\u0430\u043a \u043f\u0430\u0440\u0430\u043b\u043b\u0435\u043b\u044c\u043d\u044b\u0435 \u043f\u043e\u0434\u0432\u0430\u0440\u0438\u0430\u043d\u0442\u044b), NON-fused**;\n  3. **C \u2014 TorchOpt Adam, fused**.\n\u041e\u0441\u044c \u00abfused vs non-fused \u0432\u043d\u0443\u0442\u0440\u0438 TorchOpt\u00bb \u2014 \u043a\u043b\u044e\u0447\u0435\u0432\u0430\u044f: \u0431\u0435\u0437 \u043d\u0435\u0451 \u043c\u044b \u0438\u0437\u043c\u0435\u0440\u044f\u0435\u043c \u0440\u0430\u0437\u043d\u0438\u0446\u0443 \u00abTorchOpt \u043f\u0440\u043e\u0442\u0438\u0432 torch\u00bb, \u0430 \u043d\u0435 \u044d\u0444\u0444\u0435\u043a\u0442 fusion, \u043d\u0430 \u0447\u0451\u043c \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c \u043e\u0441\u043e\u0431\u0435\u043d\u043d\u043e \u043d\u0430\u0441\u0442\u0430\u0438\u0432\u0430\u0435\u0442, \u0438 \u044f \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u0441\u043e\u0433\u043b\u0430\u0441\u0435\u043d.\n\u041f\u0440\u043e\u0431\u043b\u0435\u043c\u0430, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u043d\u0430\u0434\u043e \u0437\u0430\u043b\u043e\u0436\u0438\u0442\u044c: torch.compile-\u0433\u0440\u0430\u0444 \u0448\u0430\u0433\u0430 (\u0443\u0441\u043b\u043e\u0432\u0438\u0435 C) \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d grad_fn-\u0442\u0440\u0430\u0441\u0441\u0438\u0440\u043e\u0432\u043a\u0435 torchviz [UNCERTAINTY]. \u0420\u0435\u0448\u0435\u043d\u0438\u0435: \u0434\u0432\u043e\u0439\u043d\u0430\u044f \u044d\u043a\u0441\u0442\u0440\u0430\u043a\u0446\u0438\u044f \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u0439 \u2014 primary: `torch.export`/fx-\u0433\u0440\u0430\u0444 \u0443\u0440\u043e\u0432\u043d\u044f aten (\u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u0442\u0440\u0451\u0445 \u0443\u0441\u043b\u043e\u0432\u0438\u0439, \u0435\u0434\u0438\u043d\u044b\u0439 \u0443\u0440\u043e\u0432\u0435\u043d\u044c \u0430\u0431\u0441\u0442\u0440\u0430\u043a\u0446\u0438\u0438); secondary: torchviz DOT-\u0433\u0440\u0430\u0444 (\u0442\u0430\u043c, \u0433\u0434\u0435 \u0441\u0442\u0440\u043e\u0438\u0442\u0441\u044f). \u041c\u0435\u0442\u0440\u0438\u043a\u0438 \u0441\u0447\u0438\u0442\u0430\u044e\u0442\u0441\u044f \u043f\u043e \u043e\u0431\u0435\u0438\u043c \u044d\u043a\u0441\u0442\u0440\u0430\u043a\u0446\u0438\u044f\u043c; \u0440\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u043c\u0435\u0436\u0434\u0443 \u044d\u043a\u0441\u0442\u0440\u0430\u043a\u0442\u043e\u0440\u0430\u043c\u0438 \u2014 \u0441\u0430\u043c \u043f\u043e \u0441\u0435\u0431\u0435 \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u0439 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u00abfused-\u0448\u0430\u0433 \u0432\u043e\u043e\u0431\u0449\u0435 \u043d\u0435 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u043c \u0432 TorchViz\u00bb \u2014 \u0432\u0430\u043b\u0438\u0434\u043d\u044b\u0439 \u043e\u0442\u0432\u0435\u0442 \u043d\u0430 \u0438\u0441\u0445\u043e\u0434\u043d\u044b\u0439 \u0432\u043e\u043f\u0440\u043e\u0441).\n\n(b) **\u041c\u0435\u0442\u0440\u0438\u043a\u0438 \u0441\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u0438 (\u043e\u0431\u044a\u0435\u043a\u0442\u0438\u0432\u043d\u044b\u0435, \u043f\u043e \u043f\u0430\u0440\u0441\u0438\u043d\u0433\u0443 DOT/graphML, \u043d\u0435 \u043f\u043e \u043a\u0430\u0440\u0442\u0438\u043d\u043a\u0430\u043c).** |V|, |E|; \u0440\u0430\u0437\u043c\u0435\u0440 \u0441\u043b\u043e\u0432\u0430\u0440\u044f \u0442\u0438\u043f\u043e\u0432 \u0443\u0437\u043b\u043e\u0432; \u0433\u043b\u0443\u0431\u0438\u043d\u0430 (\u0434\u043b\u0438\u043d\u043d\u0435\u0439\u0448\u0438\u0439 \u043f\u0443\u0442\u044c); \u043c\u0430\u043a\u0441. in/out-degree; \u0434\u0443\u0431\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435: \u0434\u043e\u043b\u044f \u043f\u043e\u0432\u0442\u043e\u0440\u044f\u044e\u0449\u0438\u0445\u0441\u044f \u043f\u043e\u0434\u0433\u0440\u0430\u0444\u043e\u0432 ( \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0445\u0435\u0448 \u0443\u0437\u043b\u0430 = op+\u0430\u0442\u0440\u0438\u0431\u0443\u0442\u044b+\u0432\u0445\u043e\u0434\u044b \u2192 1 \u2212 unique/total); **\u0434\u043e\u043b\u044f \u00ab\u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043d\u044b\u0445\u00bb \u0443\u0437\u043b\u043e\u0432** (getattr/hashtag-\u043e\u0431\u0451\u0440\u0442\u043a\u0438, contiguous, detach, view/as_strided, unpack/GetAttr, no-op) \u043f\u0440\u043e\u0442\u0438\u0432 **\u0441\u0435\u043c\u0430\u043d\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 math-\u0443\u0437\u043b\u043e\u0432** (add, mul, div, sqrt, addcmul, lerp, maximum); \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e \u0440\u0430\u0437\u043c\u0435\u0440 \u043f\u043e\u0434\u043e\u0431\u043b\u0430\u0441\u0442\u0438 \u00ab\u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0442\u043e\u0440\u00bb vs \u00ab\u043c\u043e\u0434\u0435\u043b\u044c\u00bb (\u0440\u0430\u0437\u0434\u0435\u043b\u044f\u044e\u0442\u0441\u044f \u043f\u043e \u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u043d\u043e\u0441\u0442\u0438 \u0443\u0437\u043b\u043e\u0432 optimizer-\u0437\u0430\u043c\u044b\u043a\u0430\u043d\u0438\u044e); \u043f\u0440\u043e\u043a\u0441\u0438 \u043e\u043f\u0438\u0441\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0439 \u0441\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u0438 \u2014 gzip-\u0440\u0430\u0437\u043c\u0435\u0440 \u0441\u0435\u0440\u0438\u0430\u043b\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u043e\u0433\u043e \u0433\u0440\u0430\u0444\u0430.\n\n(c) **\u0418\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0438\u0440\u0443\u0435\u043c\u043e\u0441\u0442\u044c (\u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f, \u043e\u0431\u044a\u044f\u0432\u043b\u044f\u044e \u043a\u0430\u043a \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435, \u0430 \u043d\u0435 \u043a\u0430\u043a \u0443\u0441\u0442\u043e\u044f\u0432\u0448\u0443\u044e\u0441\u044f \u043c\u0435\u0442\u0440\u0438\u043a\u0443).** Primary: \u0441\u043b\u0435\u043f\u0430\u044f \u043f\u0430\u043d\u0435\u043b\u044c (\u22655 \u0440\u0435\u0439\u0442\u0438\u043d\u0433\u043e\u0432\u0449\u0438\u043a\u043e\u0432 \u0441 \u043e\u043f\u044b\u0442\u043e\u043c PyTorch), \u0440\u0443\u0431\u0440\u0438\u043a\u0430 \u0438\u0437 3 \u0432\u043e\u043f\u0440\u043e\u0441\u043e\u0432 \u043f\u043e 5-\u0431\u0430\u043b\u043b\u044c\u043d\u043e\u0439 \u0448\u043a\u0430\u043b\u0435 (\u043b\u0435\u0433\u043a\u043e \u043b\u0438 \u043d\u0430\u0439\u0442\u0438 \u0448\u0430\u0433 \u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0442\u043e\u0440\u0430; \u043f\u0440\u043e\u0441\u043b\u0435\u0434\u0438\u0442\u044c \u043f\u0443\u0442\u044c loss\u2192\u0443\u043a\u0430\u0437\u0430\u043d\u043d\u044b\u0439 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440; \u0432\u043e\u0441\u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u0430\u044f \u0437\u0430\u0433\u0440\u043e\u043c\u043e\u0436\u0434\u0451\u043d\u043d\u043e\u0441\u0442\u044c), \u0440\u0430\u043d\u0434\u043e\u043c\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043f\u043e\u0440\u044f\u0434\u043e\u043a, \u043c\u0435\u0442\u043a\u0438 \u0443\u0441\u043b\u043e\u0432\u0438\u0439 \u0441\u043d\u044f\u0442\u044b; \u043d\u0430\u0434\u0451\u0436\u043d\u043e\u0441\u0442\u044c \u2014 Krippendorff's \u03b1; \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u2014 Friedman \u043f\u043e \u0431\u043b\u043e\u043a\u0430\u043c (\u043c\u043e\u0434\u0435\u043b\u044c\u00d7seed). Secondary behavioral-proxy: \u0432\u0440\u0435\u043c\u044f \u0438 \u043e\u0448\u0438\u0431\u043a\u0438 \u043f\u0440\u0438 \u0437\u0430\u0434\u0430\u0447\u0435 \u00ab\u0443\u043a\u0430\u0436\u0438 \u043f\u0443\u0442\u044c loss \u0434\u043e \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0430 N\u00bb \u0438 \u00ab\u043d\u0430\u0439\u0434\u0438 \u0443\u0437\u0435\u043b, \u043e\u0431\u043d\u043e\u0432\u043b\u044f\u044e\u0449\u0438\u0439 exp_avg\u00bb \u2014 \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0447\u0435\u0441\u043a\u0430\u044f \u0437\u0430\u043c\u0435\u043d\u0430 \u00ab\u043f\u043e\u043d\u044f\u0442\u043d\u043e\u0441\u0442\u0438\u00bb.\n\n(d) **\u0424\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c\u044b\u0435 \u0444\u0430\u043a\u0442\u043e\u0440\u044b \u0438 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438.** \u0410\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430, \u0447\u0438\u0441\u043b\u043e \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432, seed, dtype=device=CPU, \u0432\u0435\u0440\u0441\u0438\u0438 torch/torchopt/torchviz (pin \u043a\u043e\u043c\u043c\u0438\u0442\u043e\u0432), \u043e\u0434\u0438\u043d \u0438 \u0442\u043e\u0442 \u0436\u0435 \u044d\u043a\u0441\u0442\u0440\u0430\u043a\u0442\u043e\u0440 \u0438 \u043e\u0434\u0438\u043d \u0443\u0440\u043e\u0432\u0435\u043d\u044c \u0430\u0431\u0441\u0442\u0440\u0430\u043a\u0446\u0438\u0438 (aten), \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u0448\u0430\u0433\u043e\u0432, \u043e\u0442\u043a\u043b\u044e\u0447\u0438\u0442\u044c sources/anomaly-detection \u0440\u0430\u0437\u043b\u0438\u0447\u0438\u044f. \u0421\u043f\u0435\u0446-\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438: \u00abidentity control\u00bb \u2014 \u0434\u0432\u043e\u0439\u043d\u0430\u044f \u044d\u043a\u0441\u0442\u0440\u0430\u043a\u0446\u0438\u044f \u043e\u0434\u043d\u043e\u0433\u043e \u0433\u0440\u0430\u0444\u0430 (\u0448\u0443\u043c \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442\u0430); \u00abnull control\u00bb \u2014 \u0448\u0430\u0433 \u043f\u0440\u0438 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0438 \u0441\u0432\u044f\u0437\u0438 loss\u2194\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440 (\u043e\u0446\u0435\u043d\u043a\u0430 \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043d\u043e\u0433\u043e \u0448\u0443\u043c\u0430 \u043d\u0435-\u043e\u043f\u0442\u0438\u043c\u0438\u0437\u0430\u0442\u043e\u0440\u043d\u043e\u0433\u043e \u043f\u0440\u043e\u0438\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u044f). **Pre-registered \u0434\u0432\u0443\u0445\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0435\u0435 \u043f\u0440\u0430\u0432\u0438\u043b\u043e \u0432\u044b\u0432\u043e\u0434\u0430**: \u00ab\u043c\u0435\u043d\u0435\u0435 \u0441\u043b\u043e\u0436\u043d\u0430\u044f\u00bb \u0437\u0430\u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u0443\u0441\u043b\u043e\u0432\u0438\u0435 C \u043b\u0443\u0447\u0448\u0435 A \u0438 B \u043f\u043e \u22652/3 \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0445 \u043c\u0435\u0442\u0440\u0438\u043a \u0441 \u043d\u0435\u043f\u0435\u0440\u0435\u043a\u0440\u044b\u0432\u0430\u044e\u0449\u0438\u043c\u0438\u0441\u044f bootstrap CI; \u00ab\u0431\u043e\u043b\u0435\u0435 \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0438\u0440\u0443\u0435\u043c\u0430\u044f\u00bb \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0438 \u03b1 \u0440\u0435\u0439\u0442\u0438\u043d\u0433\u043e\u0432\u0449\u0438\u043a\u043e\u0432 \u0432\u044b\u0448\u0435 \u043f\u043e\u0440\u043e\u0433\u0430 \u0438 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u043e\u043c \u0442\u0435\u0441\u0442\u0435 \u043f\u0440\u043e\u0442\u0438\u0432 A; \u0438\u043d\u0430\u0447\u0435 \u2014 null \u0438\u043b\u0438 \u043e\u0431\u0440\u0430\u0442\u043d\u044b\u0439 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, fused-\u0433\u0440\u0430\u0444 \u00ab\u043f\u043b\u043e\u0441\u043a\u0438\u0439\u00bb \u0438 \u0441\u0435\u043c\u0430\u043d\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u043d\u0435\u043f\u0440\u043e\u0441\u043b\u0435\u0436\u0438\u0432\u0430\u0435\u043c\u044b\u0439 \u2192 \u0445\u0443\u0436\u0435 \u043f\u043e \u0440\u0435\u0439\u0442\u0438\u043d\u0433\u0443, \u043f\u0440\u0438 \u043c\u0435\u043d\u044c\u0448\u0435\u043c |V|; \u044d\u0442\u043e \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0439 \u043f\u0440\u0430\u0432\u0434\u043e\u043f\u043e\u0434\u043e\u0431\u043d\u044b\u0439 \u0438\u0441\u0445\u043e\u0434, \u0438 \u0434\u0438\u0437\u0430\u0439\u043d \u0435\u0433\u043e \u043b\u043e\u0432\u0438\u0442 \u0440\u0430\u0441\u0446\u0435\u043f\u043b\u0435\u043d\u0438\u0435\u043c \u043c\u0435\u0442\u0440\u0438\u043a \u0441\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u0438 \u0438 \u0440\u0435\u0439\u0442\u0438\u043d\u0433\u043e\u0432).\n\n## 3) \u041f\u0440\u0435\u0434\u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u0438 \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u0438 (\u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e \u043e\u0442 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0439 \u0437\u0430\u0434\u0430\u0447\u0438)\n\n- **Assumption 1.** \u041d\u0438 \u043e\u0434\u043d\u043e\u0433\u043e \u0438\u0437 \u0434\u0432\u0443\u0445 \u0440\u0435\u043f\u043e \u0432 \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0438 \u043d\u0435\u0442; \u0432\u0441\u0435 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u044f \u043e\u0431 API (torchopt.adam/init/update, step_, chain; torchviz.make_dot \u043f\u043e grad_fn; \u00abfused \u0447\u0435\u0440\u0435\u0437 torch.compile\u00bb; \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u043e\u0432\u0430\u043d\u0438\u0435 torchviz-\u0442\u0443\u0442\u043e\u0440\u0438\u0430\u043b\u0430 \u0432 \u0434\u043e\u043a\u0430\u0445 TorchOpt) \u2014 \u043f\u0440\u0435\u0434\u044b\u0434\u0443\u0449\u0438\u0435 \u0437\u043d\u0430\u043d\u0438\u044f, \u043d\u0435 \u0444\u0430\u043a\u0442\u044b \u044d\u0442\u043e\u0439 \u0441\u0440\u0435\u0434\u044b; \u043f\u043e\u0434\u043b\u0435\u0436\u0430\u0442 \u0441\u0432\u0435\u0440\u043a\u0435 \u043f\u043e \u0438\u0441\u0445\u043e\u0434\u043d\u0438\u043a\u0430\u043c \u0434\u043e \u0444\u0438\u043a\u0441\u0430\u0446\u0438\u0438 \u0434\u0438\u0437\u0430\u0439\u043d\u0430 \u0432 result.\n- **Assumption 2.** \u0412\u043e\u043f\u0440\u043e\u0441 \u043e\u0441\u043c\u044b\u0441\u043b\u0435\u043d \u0442\u043e\u043b\u044c\u043a\u043e \u043a\u0430\u043a \u00ab\u0433\u0440\u0430\u0444, \u043f\u0440\u043e\u0434\u044e\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043f\u0440\u0438 \u0442\u0440\u0430\u043d\u0441\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044f\u0445 TorchOpt (fused), \u043f\u0440\u043e\u0442\u0438\u0432 \u0433\u0440\u0430\u0444\u0430, \u043e\u0442\u0434\u0430\u043d\u043d\u043e\u0433\u043e TorchViz \u0434\u043b\u044f baseline-Adam, \u043f\u0440\u0438 \u0435\u0434\u0438\u043d\u043e\u043c \u0441\u043f\u043e\u0441\u043e\u0431\u0435 \u0438\u0437\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u044f\u00bb; \u0441\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0442\u044c \u00ab\u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442 TorchOpt\u00bb \u0441 \u00ab\u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u043e\u043c TorchViz\u00bb \u043d\u0430\u043f\u0440\u044f\u043c\u0443\u044e \u2014 \u043f\u043e\u0434\u043c\u0435\u043d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441\u0430. \u042d\u0442\u043e \u043c\u043e\u044f \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u044f, \u0442\u0440\u0435\u0431\u0443\u044e\u0449\u0430\u044f \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u044f \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u0435\u043c.\n- **Uncertainty 1.** \u0422\u0435\u0445\u043d\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u044c grad_fn-\u0433\u0440\u0430\u0444\u0430 \u0434\u043b\u044f fused/compile-\u0448\u0430\u0433\u0430 (\u0443\u0441\u043b\u043e\u0432\u0438\u0435 C) \u2014 \u0435\u0441\u043b\u0438 \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d, primary-\u044d\u043a\u0441\u0442\u0440\u0430\u043a\u0446\u0438\u044f (torch.export) \u0441\u043f\u0430\u0441\u0430\u0435\u0442 \u0434\u0438\u0437\u0430\u0439\u043d, \u043d\u043e \u043c\u0435\u043d\u044f\u0435\u0442 \u0441\u043c\u044b\u0441\u043b \u00aboutput from TorchViz\u00bb \u0434\u043b\u044f \u044d\u0442\u043e\u0433\u043e \u0443\u0441\u043b\u043e\u0432\u0438\u044f.\n- **Uncertainty 2.** \u0415\u0441\u043b\u0438 \u00abfused\u00bb \u0432 TorchOpt \u043e\u043a\u0430\u0436\u0435\u0442\u0441\u044f CUDA-only \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0435\u0439, \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043d\u0430 CPU \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e \u0431\u0435\u0437 \u0441\u043c\u0435\u043d\u044b \u0436\u0435\u043b\u0435\u0437\u0430 (\u0437\u0434\u0435\u0441\u044c GPU \u043d\u0435\u0442) \u2014 \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0437\u0430\u0440\u0430\u043d\u0435\u0435, \u043a\u0430\u043a\u043e\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 fused \u0441\u0447\u0438\u0442\u0430\u0435\u043c \u044d\u0442\u0430\u043b\u043e\u043d\u043d\u044b\u043c.\n- **Uncertainty 3.** \u0417\u043d\u0430\u0447\u0438\u043c\u0430\u044f \u0447\u0430\u0441\u0442\u044c \u00ab\u0441\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u0438\u00bb \u0433\u0440\u0430\u0444\u0430 Adam \u0432 autograd-\u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0438 \u043c\u043e\u0436\u0435\u0442 \u0432\u043e\u043e\u0431\u0449\u0435 \u043d\u0435 \u0432\u0445\u043e\u0434\u0438\u0442\u044c \u0432 loss-\u0433\u0440\u0430\u0444 (step \u043d\u0435 \u0442\u0440\u0430\u0441\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043e\u0431\u044b\u0447\u043d\u044b\u043c make_dot \u0431\u0435\u0437 `retain_graph/params=True`) \u2014 \u043e\u0431\u044a\u0451\u043c optimizer-\u043e\u0431\u043b\u0430\u0441\u0442\u0438 \u043d\u0430\u0434\u043e \u044f\u0432\u043d\u043e \u0432\u043a\u043b\u044e\u0447\u0430\u0442\u044c \u0447\u0435\u0440\u0435\u0437 `params=True` \u043b\u0438\u0431\u043e \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u0443\u044e \u044d\u043a\u0441\u0442\u0440\u0430\u043a\u0446\u0438\u044e \u0448\u0430\u0433\u0430; \u044d\u0442\u043e \u043a\u043b\u044e\u0447\u0435\u0432\u0430\u044f \u0440\u0430\u0437\u0432\u0438\u043b\u043a\u0430 \u0434\u0438\u0437\u0430\u0439\u043d\u0430.\n- **Assumption 3.** \u041f\u043e\u0440\u043e\u0433\u0438 \u043f\u0430\u043d\u0435\u043b\u0438 (5 \u0440\u0435\u0439\u0442\u0438\u043d\u0433\u043e\u0432\u0449\u0438\u043a\u043e\u0432, \u03b1>0.667 \u0438 \u0442.\u043f.) \u2014 \u0440\u0430\u0431\u043e\u0447\u0438\u0435 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u044f, \u043d\u0435 \u0432\u043d\u0435\u0448\u043d\u0438\u0435 \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u044b.\n- \u042d\u043c\u043f\u0438\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0438\u0441\u0445\u043e\u0434Unknown \u043f\u043e \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u0438\u044e: \u0434\u0438\u0437\u0430\u0439\u043d \u0434\u0432\u0443\u0445\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0438\u0439, null \u0438 \u043e\u0431\u0440\u0430\u0442\u043d\u044b\u0439 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b \u043f\u0440\u0435\u0434\u0443\u0441\u043c\u043e\u0442\u0440\u0435\u043d\u044b \u043f\u0440\u0430\u0432\u0438\u043b\u0430\u043c\u0438 \u0432\u044b\u0432\u043e\u0434\u0430. \u041d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u043b\u043e\u0441\u044c \u0438 \u043d\u0435 \u00ab\u0434\u043e\u043a\u0430\u0437\u0430\u043d\u043e\u00bb.", "evidence": "\u0424\u0430\u043a\u0442\u044b \u0438\u043d\u0441\u043f\u0435\u043a\u0446\u0438\u0438 (\u043a\u043e\u043c\u0430\u043d\u0434\u044b \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u044b): ls /workspace \u2192 \u0442\u043e\u043b\u044c\u043a\u043e task.json (466 B, \u0442\u0435\u043a\u0441\u0442 \u0432\u043e\u043f\u0440\u043e\u0441\u0430 + track.md \u00abdesign-only, repositories and compute not required\u00bb); find / -maxdepth 4 -iname '*torchopt*' -o -iname '*torchviz*' \u2192 \u043f\u0443\u0441\u0442\u043e; /home/actor \u043f\u0443\u0441\u0442; python 3.14.4; import torch/torchopt/torchviz/graphviz \u2192 ModuleNotFoundError (4 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438); dot CLI \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442; *.whl \u0438 pip-\u043a\u044d\u0448 \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d\u044b; git 2.53.0; \u0441\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430. \u0412\u044b\u0432\u043e\u0434: source-verified API-\u0444\u0430\u043a\u0442\u044b \u043e TorchOpt/TorchViz \u043f\u043e\u043b\u0443\u0447\u0438\u0442\u044c \u0441\u0435\u0439\u0447\u0430\u0441 \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e \u2014 \u0432 \u0434\u0438\u0437\u0430\u0439\u043d\u0435 \u043e\u043d\u0438 \u044f\u0432\u043d\u043e \u043c\u0430\u0440\u043a\u0438\u0440\u043e\u0432\u0430\u043d\u044b \u043a\u0430\u043a \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c\u044b\u0435 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f. \u041d\u0438\u043a\u0430\u043a\u0438\u0445 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u043e\u0432 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u043e\u0432 \u043d\u0435 \u0441\u0433\u0435\u043d\u0435\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043e \u0438 \u043d\u0435 \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u043e.", "assumptions": ["\u0412\u0441\u0435 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u044f \u043e\u0431 API TorchOpt (torchopt.adam init/update, stateful step_, chain, fused=torch.compile) \u0438 TorchViz (make_dot \u043f\u043e grad_fn-\u0433\u0440\u0430\u0444\u0443, params=True) \u043e\u0441\u043d\u043e\u0432\u0430\u043d\u044b \u043d\u0430 \u043f\u0440\u0435\u0434\u044b\u0434\u0443\u0449\u0438\u0445 \u0437\u043d\u0430\u043d\u0438\u044f\u0445 \u0438 \u043d\u0435 \u0432\u0435\u0440\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u044b \u0432 \u0434\u0430\u043d\u043d\u043e\u0439 \u0441\u0440\u0435\u0434\u0435 \u2014 \u0440\u0435\u043f\u043e \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0442", "